def solve(rows):
    filtered_rows = [row for row in rows if row['day'] <= 20]
    site_data = {}
    for row in filtered_rows:
        site = row['site']
        phase = row['phase']
        if site not in site_data:
            site_data[site] = {'returned': 0, 'total': 0}
        site_data[site]['total'] += 1
        if phase == 'returned':
            site_data[site]['returned'] += 1
    result = []
    for site, data in site_data.items():
        percentage = round(100 * data['returned'] / data['total'], 1)
        if percentage >= 20:
            result.append((percentage, site))
    result.sort(key=lambda x: (-x[0], x[1]))
    return result
```

