def solve(rows):
    filtered_rows = [row for row in rows if row['outcome'] == 'completed']
    days = sorted(set(row['day'] for row in filtered_rows))
    max_length = 0
    start_day = None
    current_length = 1
    current_start = days[0]

    for i in range(1, len(days)):
        if days[i] == days[i - 1] + 1:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                start_day = current_start
            current_length = 1
            current_start = days[i]

    if current_length > max_length:
        max_length = current_length
        start_day = current_start

    if max_length == 0:
        return [0, None]
    else:
        return [max_length, start_day]
