def solve(rows):
    # Filter rows where day is 18 or less
    filtered_rows = [row for row in rows if row["day"] <= 18]

    # If no rows, return empty list
    if not filtered_rows:
        return []

    # Group rows by department
    department_data = {}
    for row in filtered_rows:
        department = row["department"]
        if department not in department_data:
            department_data[department] = {"total": 0, "completed": 0}
        department_data[department]["total"] += 1
        if row["outcome"] == "completed":
            department_data[department]["completed"] += 1

    # Calculate percentage for each department
    result = []
    for department in department_data:
        total = department_data[department]["total"]
        completed = department_data[department]["completed"]
        if total == 0:
            continue
        percentage = round(100 * (completed / total), 1)
        if percentage >= 30:
            result.append((percentage, department))

    # Sort by percentage (descending) and then by department (ascending)
    result.sort(key=lambda x: (-x[0], x[1]))

    # Format the result as [value, percentage] pairs
    formatted_result = []
    for percentage, department in result:
        formatted_result.append([department, percentage])

    return formatted_result
