    filtered_rows = list(set(filtered_rows))
    filtered_rows.sort()
    max_length = 0
    start_day = None
    current_length = 1
    for i in range(1, len(filtered_rows)):
        if filtered_rows[i] == filtered_rows[i - 1] + 1:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                start_day = filtered_rows[i - 1] - current_length + 1
            current_length = 1
    if current_length > max_length:
        max_length = current_length
        start_day = filtered_rows[-1] - current_length + 1
    return [max_length, start_day]
