        units = row['units']
        weight_kg = row['weight_kg']
        key = (site, units * weight_kg)
        if key not in site_totals:
            site_totals[key] = 0
        site_totals[key] += 1
    if not site_totals:
        return None
    max_value = max(site_totals.values())
