def solve(rows):
    # Filter rows where phase is not 'held'
    filtered_rows = [row for row in rows if row['phase'] != 'held']

    if not filtered_rows:
        return None

    # Group by carrier and calculate median units
    carrier_units = {}
    for row in filtered_rows:
        carrier = row['carrier']
        units = row['units']
        weight_kg = row['weight_kg']
        carrier_units[carrier] = carrier_units.get(carrier, []) + [units]

    # Calculate median units for each carrier
    median_units = {}
    for carrier, units_list in carrier_units.items():
        n = len(units_list)
        if n % 2 == 1:
            median = sorted(units_list)[n // 2]
        else:
            median = (sorted(units_list)[n // 2 - 1] + sorted(units_list)[n // 2]) / 2
        median_units[carrier] = round(median, 1)

    # Return the carrier with the highest median units, alphabetically first on tie
    if not median_units:
        return None

    max_median = -1
    best_carrier = None
    for carrier, median in median_units.items():
        if median > max_median or (median == max_median and carrier < best_carrier):
            max_median = median
            best_carrier = carrier

    return best_carrier
