def solve(rows):
    # Filter rows where depot is 'alpha' or 'delta'
    filtered_rows = [row for row in rows if row['depot'] in ['alpha', 'delta']]

    # Find the longest block of consecutive integers in 'day' field
    if not filtered_rows:
        return [0, None]

    # Extract day values
    days = [row['day'] for row in filtered_rows]

    # Find the longest consecutive integer block
    max_block = [0, None]
    current_block = []

    for day in days:
        if day == current_block[-1] + 1:
            current_block.append(day)
        else:
            if current_block:
                if len(current_block) > len(max_block):
                    max_block = current_block
                current_block = [day]

    if current_block:
        if len(current_block) > len(max_block):
            max_block = current_block
    else:
        max_block = [0, None]

    return [len(max_block), max_block[0]] if max_block[0] is not None else [0, None]
