def solve(rows):
    # Filter rows where outcome is 'completed'
    completed_rows = [row for row in rows if row['outcome'] == 'completed']

    # Group by doctor and collect duration_min values
    doctor_durations = {}
    for row in completed_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor not in doctor_durations:
            doctor_durations[doctor] = []
        doctor_durations[doctor].append(duration)

    # Calculate median for each doctor
    result = {}
    for doctor, durations in doctor_durations.items():
        durations.sort()
        n = len(durations)
        mid = n // 2
        if n % 2 == 1:
            median = durations[mid]
        else:
            median = (durations[mid - 1] + durations[mid]) / 2
        result[doctor] = round(median, 1)

    return result
```

