def solve(rows):
    filtered_rows = [row for row in rows if row['weight_kg'] < 157]
    site_data = {}
    for row in filtered_rows:
        site = row['site']
        if site not in site_data:
            site_data[site] = {'shipped': 0, 'total': 0}
        site_data[site]['total'] += 1
        if row['phase'] == 'shipped':
            site_data[site]['shipped'] += 1

    result = []
    for site, data in site_data.items():
        shipped = data['shipped']
        total = data['total']
        if total == 0:
            continue
        percentage = round(100 * (shipped / total), 1)
        if percentage >= 30:
            result.append([site, percentage])

    # Sort by percentage descending, then by site ascending
    result.sort(key=lambda x: (-x[1], x[0]))
    return result
```

