def solve(rows):
    filtered_rows = [row for row in rows if row['outcome'] != 'no_show']
    department_data = {}
    for row in filtered_rows:
        department = row['department']
        if department not in department_data:
            department_data[department] = {'total': 0, 'no_show': 0}
        department_data[department]['total'] += 1
    no_show_count = {}
    for row in rows:
        if row['outcome'] == 'no_show':
            department = row['department']
            if department not in no_show_count:
                no_show_count[department] = 0
            no_show_count[department] += 1
    result = []
    for department in department_data:
        total = department_data[department]['total']
        no_show = no_show_count.get(department, 0)
        percentage = round(100 * no_show / total, 1)
        if percentage >= 20:
            result.append((percentage, department))
    result.sort(key=lambda x: (-x[0], x[1]))
    return result
