def solve(rows):
    filtered_rows = [row for row in rows if row['packages'] >= 5]
    depot_data = {}
    for row in filtered_rows:
        depot = row['depot']
        result = row['result']
        if depot not in depot_data:
            depot_data[depot] = {'late': 0, 'total': 0}
        depot_data[depot]['total'] += 1
        if result == 'late':
            depot_data[depot]['late'] += 1
    result = []
    for depot, data in depot_data.items():
        percentage = round(100 * data['late'] / data['total'], 1)
        if percentage >= 20:
            result.append((percentage, depot))
    result.sort(key=lambda x: (-x[0], x[1]))
    return result
```

