def solve(rows):
    # Group rows by department
    department_groups = {}
    for row in rows:
        department = row['department']
        if department not in department_groups:
            department_groups[department] = []
        department_groups[department].append(row)

    # Calculate completed visits for each department
    completed_counts = {}
    for department, group in department_groups.items():
        completed_counts[department] = sum(1 for row in group if row['outcome'] == 'completed')

    # Calculate total visits for each department
    total_counts = {}
    for department, group in department_groups.items():
        total_counts[department] = len(group)

    # Calculate percentages for each department
    percentages = {}
    for department, count in completed_counts.items():
        total = total_counts[department]
        if total == 0:
            percentage = 0.0
        else:
            percentage = (count / total) * 100
        percentages[department] = (round(100 * percentage, 1), percentage)

    # Filter percentages >= 35%
    filtered_percentages = [
        (value, percentage) for (value, percentage) in percentages.items()
        if percentage >= 35
    ]

    # Sort by percentage (descending), then by value (alphabetically)
    filtered_percentages.sort(key=lambda x: (-x[1], x[0]))

    # Return the result
    return [(value, percentage) for (value, percentage) in filtered_percentages]
```

