    doctor_durations = {}
    for row in filtered_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor in doctor_durations:
            doctor_durations[doctor] += duration
        else:
            doctor_durations[doctor] = duration
    sorted_doctors = sorted(doctor_durations.items(), key=lambda x: (-x[1], x[0]))
    if len(sorted_doctors) >= 2:
        return sorted_doctors[1][0]
    else:
        return None
