def solve(rows):
    # Filter rows where outcome is not 'rescheduled'
    filtered_rows = [row for row in rows if row['outcome'] != 'rescheduled']

    # Sum duration_min per doctor
    doctor_duration = {}
    for row in filtered_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor in doctor_duration:
            doctor_duration[doctor] += duration
        else:
            doctor_duration[doctor] = duration

    # Sort doctors by total duration (descending) and then alphabetically (ascending)
    sorted_doctors = sorted(doctor_duration.items(), key=lambda x: (-x[1], x[0]))

    # Return the second doctor or None if there are fewer than two
    if len(sorted_doctors) >= 2:
        return sorted_doctors[1][0]
    else:
        return None
