def solve(rows):
    filtered_rows = [row for row in rows if row['outcome'] != 'no_show']
    doctor_durations = {}
    for row in filtered_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor not in doctor_durations:
            doctor_durations[doctor] = [duration]
        else:
            doctor_durations[doctor].append(duration)
    result = {}
    for doctor, durations in doctor_durations.items():
        durations.sort()
        n = len(durations)
        if n == 0:
            continue
        if n % 2 == 1:
            median = durations[n // 2]
        else:
            median = (durations[n // 2 - 1] + durations[n // 2]) / 2
        result[doctor] = round(median, 1)
    return result
