def solve(rows):
    filtered_rows = [row for row in rows if row['outcome'] != 'no_show']
    sorted_rows = sorted(filtered_rows, key=lambda x: (x['day'], x['visit_id']))
    balance = 0
    min_balance = 0
    earliest_day = None
    for row in sorted_rows:
        if row['outcome'] == 'completed':
            balance -= row['duration_min']
        elif row['outcome'] == 'no_show':
            balance += row['duration_min']
        else:
            continue
        if balance < min_balance:
            min_balance = balance
            earliest_day = row['day']
    return [min_balance, earliest_day] if earliest_day is not None else [0, None]
