def solve(rows):
    # Filter rows where outcome is either 'no_show' or 'completed'
    relevant_rows = [row for row in rows if row['outcome'] in ['no_show', 'completed']]

    # Sum duration_min per doctor
    doctor_totals = {}
    for row in relevant_rows:
        doctor = row['doctor']
        duration = row['duration_min']
        if doctor not in doctor_totals:
            doctor_totals[doctor] = 0
        doctor_totals[doctor] += duration

    # Sort doctors by total duration (descending), then alphabetically (ascending)
    sorted_doctors = sorted(doctor_totals.items(), key=lambda x: (-x[1], x[0]))

    # Return the second doctor or None if fewer than two are present
    if len(sorted_doctors) >= 2:
        return sorted_doctors[1][0]
    else:
        return None
```

