def solve(rows):
    # Initialize variables
    balance = 0
    min_balance = 0
    min_day = None

    # Process each row
    for row in rows:
        outcome = row['outcome']
        if outcome == 'no_show':
            # 'no_show' rows add duration_min
            duration = row['duration_min']
