def solve(rows):
    # Create a dictionary to store the median packages per driver
    driver_packages = {}

    # Process each row to calculate median packages per driver
    for row in rows:
        driver = row['driver']
        packages = row['packages']
        if driver not in driver_packages:
            driver_packages[driver] = []
        driver_packages[driver].append(packages)

    # Calculate median packages for each driver
    for driver, packages_list in driver_packages.items():
        packages_list.sort()
        n = len(packages_list)
        if n % 2 == 1:
            median = (packages_list[n // 2] + packages_list[n // 2 + 1]) / 2
        else:
            median = (packages_list[n // 2 - 1] + packages_list[n // 2]) / 2
        driver_packages[driver] = round(median, 1)

    # Filter rows where result is not 'late' and driver's median packages is >= 5
    filtered_rows = [
        row for row in rows
        if row['result'] != 'late'
        and row['driver'] in driver_packages
        and driver_packages[row['driver']] >= 5
    ]

    # Return the count of such rows
    return len(filtered_rows)
