def solve(rows):
    filtered_rows = [row for row in rows if row['day'] <= 15]
    if not filtered_rows:
        return [0, None]
    # Sort rows by day and then by trip_id
    filtered_rows.sort(key=lambda x: (x['day'], x['trip_id']))
    balance = 0
    min_balance = 0
    earliest_day = None
    for row in filtered_rows:
        result = row['result']
        if result == 'on_time':
            balance += row['packages']
        elif result == 'late':
            balance -= row['packages']
        else:
            continue
        if balance < min_balance:
            min_balance = balance
            earliest_day = row['day']
    return [min_balance, earliest_day]
