                balance += row['units']
            else:
                balance -= row['units']

            # Update min balance and day
            if balance < min_balance:
                min_balance = balance
                min_day = row['day']

    # Return the result
    if min_balance == float('inf'):
        return [0, None]
    else:
        return [min_balance, min_day]
