def solve(rows):
    # Group rows by depot
    depot_groups = {}
    for row in rows:
        depot = row['depot']
        if depot not in depot_groups:
            depot_groups[depot] = []
        depot_groups[depot].append(row)

    # Calculate percentage for each depot
    result_late_count = 0
    percentage_results = {}

    for depot, depot_rows in depot_groups.items():
        late_count = sum(1 for row in depot_rows if row['result'] == 'late')
        total_count = len(depot_rows)

        if total_count == 0:
            percentage = 0.0
        else:
            percentage = (late_count / total_count) * 100

        if percentage >= 30:
            percentage_results[depot] = round(percentage, 1)

        result_late_count += late_count

    # Sort by percentage (descending), then by depot (alphabetically)
    sorted_result = sorted(percentage_results.items(), key=lambda x: (-x[1], x[0]))

    # Prepare output
    output = []
    for depot, percentage in sorted_result:
        if percentage >= 30:
            output.append((depot, percentage))

    # Return the result
    return output
