    # Group rows by depot
    depot_groups = {}
    for row in rows:
        depot = row['depot']
        if depot not in depot_groups:
            depot_groups[depot] = []
        depot_groups[depot].append(row)

    # Calculate percentage for each depot
    result_late_count = 0
    percentage_results = {}

    for depot, depot_rows in depot_groups.items():
        late_count = sum(1 for row in depot_rows if row['result'] == 'late')
        total_count = len(depot_rows)
        if total_count == 0:
            percentage = 0.0
        else:
            percentage = (late_count / total_count) * 100
        percentage_results[depot] = (late_count, percentage)
        result_late_count += late_count

    # Filter percentages >= 30 and sort
    filtered_results = []
    for depot, (late_count, percentage) in percentage_results.items():
        if percentage >= 30:
            filtered_results.append((depot, late_count, percentage))

    # Sort by percentage (descending), then by depot (alphabetically)
    filtered_results.sort(key=lambda x: (-x[2], x[0]))

    # Prepare output
    output = []
    for depot, late_count, percentage in filtered_results:
        value = round(late_count, 2)
        percentage_value = round(percentage, 1)
        output.append((value, percentage_value))

    return output
```

