def solve(rows):
    # Filter rows where depot is 'alpha' or 'delta'
    filtered_rows = [row for row in rows if row['depot'] in {'alpha', 'delta'}]

    # Group by driver
    driver_groups = {}
    for row in filtered_rows:
        driver = row['driver']
        if driver not in driver_groups:
            driver_groups[driver] = []
        driver_groups[driver].append(row)

    # Sum packages per driver
    package_totals = {}
    for driver, rows in driver_groups.items():
        total = sum(row['packages'] for row in rows)
        package_totals[driver] = total

    # Sort drivers by package total (descending), then alphabetically if tied
    sorted_drivers = sorted(
        driver_groups.keys(),
        key=lambda x: (-package_totals[x], x)
    )

    # Find the second ranked driver
    if len(sorted_drivers) >= 2:
        second_driver = sorted_drivers[1]
        return (second_driver, package_totals[second_driver])
    else:
        return None
